import { INSTRUMENT_BY_ID } from './instruments.js';

/**
 * On-disk format for an imported drum kit:
 *
 *   <kit-id>/kit.json
 *   <kit-id>/samples/<instrumentId>/<sample>.wav
 *
 * The JSON file is the only link between an instrument slot and a sample path.
 * It is intentionally small so it can be regenerated by the import wizard.
 */

export const KIT_CONFIG_FILE = 'kit.json';
export const SAMPLES_DIRECTORY = 'samples';
export const KIT_FORMAT_VERSION = 1;

export function sanitizeFileName(fileName, fallback = 'sample.wav') {
  const base = String(fileName || '').split(/[\\/]/).pop() || fallback;
  const cleaned = base
    .replace(/[^\w.\- ]+/g, '_')
    .replace(/\s+/g, '_')
    .replace(/_{2,}/g, '_')
    .replace(/^\.+/, '');
  return cleaned.slice(0, 120) || fallback;
}

export function sanitizeKitId(name, fallback = 'drumkit') {
  const cleaned = String(name || '')
    .toLowerCase()
    .replace(/[^\w-]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return cleaned.slice(0, 60) || fallback;
}

export function buildSamplePath(instrumentId, fileName) {
  return `${SAMPLES_DIRECTORY}/${instrumentId}/${sanitizeFileName(fileName)}`;
}

export function buildKitConfig({ id, name, assignments }) {
  const instruments = {};
  for (const assignment of assignments) {
    if (!assignment || !INSTRUMENT_BY_ID.has(assignment.instrumentId)) continue;
    instruments[assignment.instrumentId] = {
      file: buildSamplePath(assignment.instrumentId, assignment.fileName),
      label: sanitizeFileName(assignment.fileName),
    };
  }

  return {
    id: sanitizeKitId(id),
    name: String(name || id || 'Imported Kit').slice(0, 120),
    version: KIT_FORMAT_VERSION,
    instruments,
  };
}

/**
 * Validate a parsed kit.json. Returns null when the file cannot be used.
 */
export function parseKitConfig(data) {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return null;

  const instruments = {};
  for (const [instrumentId, entry] of Object.entries(data.instruments || {})) {
    if (!INSTRUMENT_BY_ID.has(instrumentId) || !entry || typeof entry.file !== 'string') continue;
    const expectedPrefix = `${SAMPLES_DIRECTORY}/${instrumentId}/`;
    if (!entry.file.startsWith(expectedPrefix)) continue;
    if (entry.file.includes('..') || entry.file.includes('\\')) continue;
    instruments[instrumentId] = { file: entry.file };
  }

  return {
    id: sanitizeKitId(data.id),
    name: String(data.name || data.id || 'Drum Kit').slice(0, 120),
    version: KIT_FORMAT_VERSION,
    instruments,
  };
}

export function getConfiguredInstrumentIds(config) {
  return config ? Object.keys(config.instruments) : [];
}
